import { realpathSync } from "node:fs";
import { gzipSync, gunzipSync, gunzip } from "node:zlib";
import { promisify } from "node:util";
import { createProviderReceiptObserver } from "./pilot/gateway-receipts.mjs";
const entry=realpathSync(Bun.which("omp"));
const {countTokens,Encoding}=await import(import.meta.resolve("@oh-my-pi/pi-natives",entry));
const original=JSON.stringify({model:"claude-sonnet-4-6",max_tokens:4096,messages:[{role:"user",content:"bounded loopback request ".repeat(128)}],stream:true});
const event=value=>`event: ${value.type}\ndata: ${JSON.stringify(value)}\n\n`.replaceAll("\\n","\n");
let requests=0,wireMatched=false,noCredentialHeaders=false;
const server=Bun.serve({hostname:"127.0.0.1",port:0,fetch:async request=>{
  requests++;
  noCredentialHeaders=!request.headers.has("authorization")&&!request.headers.has("x-api-key");
  if(request.headers.get("content-encoding")!=="gzip")throw new Error("Expected gzip wire input");
  wireMatched=gunzipSync(await request.arrayBuffer()).toString("utf8")===original;
  if(!wireMatched)throw new Error("Wire input changed");
  return new Response(event({type:"message_start",message:{usage:{input_tokens:12,output_tokens:0}}})+event({type:"message_delta",delta:{stop_reason:"refusal",stop_details:{type:"refusal",category:"general_harms"}},usage:{output_tokens:2}})+event({type:"message_stop"}),{headers:{"content-type":"text/event-stream"}});
}});
try{
  const observer=createProviderReceiptObserver({fetch:globalThis.fetch,countTokens:text=>countTokens(text,Encoding.ClaudeV3)});
  const response=await observer.fetch(server.url,{method:"POST",headers:{"content-encoding":"gzip"},body:gzipSync(original)});
  await response.text();
  const receipt=await observer.finish();
  if(!receipt||receipt.countingError||receipt.inputTokens!==countTokens(original,Encoding.ClaudeV3)||receipt.maxOutputTokens!==4096||requests!==1||!wireMatched||!noCredentialHeaders)throw new Error("Actual Bun fetch receipt did not settle correctly");
  let limitCode;
  try{await promisify(gunzip)(gzipSync(Buffer.alloc(17*1024*1024)),{maxOutputLength:16*1024*1024});}catch(error){limitCode=error.code;}
  if(limitCode!=="ERR_BUFFER_TOO_LARGE")throw new Error("Bun gunzip limit not enforced");
  console.log(JSON.stringify({runtime:"bun",runtime_version:Bun.version,real_bun_fetch:true,requests,wire_gzip_unchanged:wireMatched,body_readable_after_fetch:true,native_token_count:receipt.inputTokens,max_output_tokens:receipt.maxOutputTokens,refusal_category:receipt.refusal.category,no_credential_headers:noCredentialHeaders,decompression_limit_mib:16,decompression_fixture_mib:17,decompression_error:limitCode,model_calls:0,server_closed_in_finally:true}));
}finally{await server.stop(true);}
